m=re.search(r'<script type="application/ld\+json">(\{"@context": "https://schema.org", "@type": "ItemList".*?\})</script>',idx)
if m:
    obj=json.loads(m.group(1)); elems=obj.get('itemListElement',[]); urls={e['url'] for e in elems}
    for a in articles:
        url=f'https://shoplovanest.com/blog/{a["slug"]}/'
        if url not in urls: elems.append({'@type':'ListItem','position':len(elems)+1,'url':url,'name':a['title']})
    obj['numberOfItems']=len(elems)
    for i,e in enumerate(elems,1): e['position']=i
    idx=idx[:m.start(1)]+json.dumps(obj,ensure_ascii=False)+idx[m.end(1):]
idx=re.sub(r'content="\d+ discreet, adult-only sexual wellness guides', f'content="{len([p for p in BLOG.iterdir() if p.is_dir() and p.name!="assets"])} discreet, adult-only sexual wellness guides', idx)
idxp.write_text(idx,encoding='utf-8')

smp=ROOT/'upload/sitemap.xml'; sm=smp.read_text(encoding='utf-8')
for a in articles:
    loc=f'https://shoplovanest.com/blog/{a["slug"]}/'
    entry=f'''  <url>\n    <loc>{loc}</loc>\n    <lastmod>{DATE}</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.70</priority>\n    <image:image>\n      <image:loc>https://shoplovanest.com{a['image']}</image:loc>\n      <image:title>{escape(a['title'])}</image:title>\n      <image:caption>{escape(a['image_alt'])}</image:caption>\n    </image:image>\n  </url>\n'''
    if loc in sm: sm=re.sub(r'  <url>\s*<loc>'+re.escape(loc)+r'</loc>.*?</url>\s*', entry, sm, flags=re.S)
    else: sm=sm.replace('</urlset>',entry+'</urlset>')
sm=re.sub(r'(<loc>https://shoplovanest.com/blog/</loc>\s*<lastmod>)[^<]+', r'\g<1>'+DATE, sm)
smp.write_text(sm,encoding='utf-8')

state={'date':DATE,'timezone':'Asia/Shanghai','status':'generated_pending_images_validation_deploy_email','article_quota':2,'articles':[{'slug':a['slug'],'title':a['title'],'url':f'https://shoplovanest.com/blog/{a["slug"]}/','primary_keywords':a['keywords'],'keyword_source':a['source'],'intent_cluster':a['intent']} for a in articles],'index_updated':True,'sitemap_updated':True,'generated_at':datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()}
(ROOT/'output/daily_blog_automation_state.json').write_text(json.dumps(state,ensure_ascii=False,indent=2),encoding='utf-8')
(ROOT/f'output/daily_blog_report_{DATE}.md').write_text('# ShopLovaNest Daily Blog Report - 2026-07-03\n\nStatus: generated; images/validation/deploy/email pending.\n\n'+'\n'.join(f'- {a["title"]}: https://shoplovanest.com/blog/{a["slug"]}/' for a in articles)+'\n',encoding='utf-8')
